import{z as n,x as B,o as l,c as p,q as r,j as s,D as e,d as t,s as A,S as i,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"分配器攻击","description":"","frontmatter":{"title":"分配器攻击","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/heap-allocator-attacks.md","filePath":"cs/heap-allocator-attacks.md","lastUpdated":1791063341000}'),d={name:"cs/heap-allocator-attacks.md"};function c(h,a,m,u,D,f){const o=B("Mermaid");return l(),p("div",null,[a[2]||(a[2]=r('<h1 id="分配器攻击" tabindex="-1">分配器攻击 <a class="header-anchor" href="#分配器攻击" aria-label="Permalink to &quot;分配器攻击&quot;">​</a></h1><div class="epigraph"><p>分配器在块头里记账：大小、空闲链表。用户数据溢出进块头，等于让 malloc 按敌手的账本工作。加固分配器把元数据与用户数据隔开、把链表指针加密，仍不是内存安全。</p><footer>—— 据 Doug Lea 的分配器叙述；Szekeres SoK；对照 ptmalloc/jemalloc 的加固演进</footer></div><p>上一课<a href="/cs/heap-uaf">UAF</a>已经能串对象。缺口是<strong>分配器元数据</strong>作为额外攻击面。本课讲为何溢出/双重释放会破坏堆契约，以及隔离与校验指针一类防御——不给改链表的操作序列。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>经典 chunk 把 size 与 fd/bk 放在用户数据旁边。溢出改 fd 则空闲链表被劫持——只陈述性质。双重释放让同一块进两次表。缺口是：分配器是 TCB，要校验与隔离。</p><p><span class="marginnote">术语翻译：TCB（可信计算基）就是「你不得不无条件信任的那一小圈代码」。malloc/free 在进程里无处不在——每次分配释放都要经过它；它被教会按别人的账本工作，就等于交出写入原语，所以必须算进 TCB。</span></p><h3 id="不是「选用某-libc-就结束」" tabindex="-1">不是「选用某 libc 就结束」 <a class="header-anchor" href="#不是「选用某-libc-就结束」" aria-label="Permalink to &quot;不是「选用某 libc 就结束」&quot;">​</a></h3><p>加固提高代价。任意写仍可能。安全语言减少到达分配器的路径。</p><p><span class="marginnote">dlmalloc 叙事是历史对照。今日分配器有 cookie、随机、隔离。本课禁止利用笔记。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：内联元数据 vs 隔离页。列出防御：canary 式 chunk 校验、unlink 检查、隔离释放。指向 sanitizer 与 fuzzer 后课。</p><p><span class="marginnote">直觉类比：chunk 校验像账本骑缝章——记账时在块头旁盖一个分配器用秘密算出的「章」，释放时重算比对；溢出者改了账本却算不出正确的章，free 一眼识破。它挡「盲改」，挡不住有信息泄露渠道的定向攻击。</span></p>',13)),(l(),s(i,null,{default:e(()=>[A(o,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20USER%5B%22%E7%94%A8%E6%88%B7%E6%95%B0%E6%8D%AE%22%5D%20--%3E%20OVF%5B%22%E6%BA%A2%E5%87%BA%E8%BF%9B%E5%9D%97%E5%A4%B4%22%5D%0A%20%20OVF%20--%3E%20META%5B%22%E7%A9%BA%E9%97%B2%E9%93%BE%E8%A1%A8%E8%A2%AB%E7%A0%B4%E5%9D%8F%22%5D%0A%20%20ISO%5B%22%E5%85%83%E6%95%B0%E6%8D%AE%E9%9A%94%E7%A6%BB%22%5D%20--%3E%20HARD%5B%22%E6%8F%90%E9%AB%98%E4%BB%A3%E4%BB%B7%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[t("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"堆完整性是分配器不变量。整数溢出下一课常是「算错长度再交给分配器/复制」的上游。",-1)),a[5]||(a[5]=E("p",null,"同一块内存，元数据放在哪里决定了攻击面：",-1)),(l(),s(i,null,{default:e(()=>[A(o,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20FREE%5B%22free(p)%3A%20%E8%AF%BB%E5%9D%97%E5%A4%B4%E8%AE%B0%E8%B4%A6%22%5D%20--%3E%20Q%7B%22%E5%85%83%E6%95%B0%E6%8D%AE%E6%94%BE%E5%93%AA%3F%22%7D%0A%20%20Q%20--%20%22%E5%86%85%E8%81%94%2C%20%E6%8C%A8%E7%9D%80%E7%94%A8%E6%88%B7%E6%95%B0%E6%8D%AE%22%20--%3E%20OVF%5B%22%E6%BA%A2%E5%87%BA%E5%8F%AF%E8%A6%86%E5%86%99%E8%B4%A6%E6%9C%AC%22%5D%0A%20%20OVF%20--%3E%20HIJACK%5B%22%E7%A9%BA%E9%97%B2%E9%93%BE%E8%A1%A8%E6%8C%89%E5%81%87%E8%B4%A6%E6%9C%AC%E8%B5%B0%22%5D%0A%20%20Q%20--%20%22%E9%9A%94%E7%A6%BB%E5%88%B0%E7%8B%AC%E7%AB%8B%E4%BF%9D%E6%8A%A4%E5%8C%BA%22%20--%3E%20SAFE%5B%22%E7%94%A8%E6%88%B7%E6%BA%A2%E5%87%BA%E5%86%99%E4%B8%8D%E5%88%B0%E8%B4%A6%E6%9C%AC%22%5D%0A%20%20SAFE%20--%3E%20CHK%5B%22%E9%87%8A%E6%94%BE%E5%89%8D%E5%86%8D%E9%AA%8C%20cookie%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=r('<p><span class="marginnote">常见误区：初学者容易以为「换上加固分配器=内存安全」。这些手段把每步利用从「直接写」抬到「先泄地址、再绕校验」，代价翻了几倍，但任意写一旦成立仍可能穿透。真正的内存安全要靠类型/内存安全语言兜底。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课无 unlink 配方。整数溢出漏洞下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>UAF 串对象；溢出/双重释放可直接改分配器账本。</li><li>隔离元数据与校验指针是加固。</li><li>仍非内存安全。</li><li>下一课整数溢出。</li><li>出处：Szekeres et al.；Doug Lea allocator notes；对照 CWE-122/415。</li></ul>',5))])}const _=n(d,[["render",c]]);export{C as __pageData,_ as default};
